import React from 'react';
import { motion } from 'framer-motion';
import './index.css';
import { ExternalLink } from 'lucide-react';

const containerVariants = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.1 } }
};

const cardVariants = {
  hidden: { opacity: 0, y: 32 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.5, ease: 'easeOut' } }
};

const handleCardGlow = (e) => {
  const card = e.currentTarget;
  const rect = card.getBoundingClientRect();
  const px = (e.clientX - rect.left) / rect.width;
  const py = (e.clientY - rect.top) / rect.height;
  const rx = (py - 0.5) * -14;
  const ry = (px - 0.5) * 14;
  card.style.transform = `perspective(900px) translateY(-6px) rotateX(${rx}deg) rotateY(${ry}deg)`;
  card.style.setProperty('--mouse-x', `${e.clientX - rect.left}px`);
  card.style.setProperty('--mouse-y', `${e.clientY - rect.top}px`);
  card.style.setProperty('--mx', `${px * 100}%`);
  card.style.setProperty('--my', `${py * 100}%`);
};

const resetCardTilt = (e) => {
  e.currentTarget.style.transform = '';
};

const Products = () => {
  return (
    <section id="products" className="section">
        <div className="container">
          <h2 className="section-title">Products</h2>
          <motion.div
            className="projects-grid"
            variants={containerVariants}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: '-60px' }}
          >
            {[
              {
                title: "NablaQuant",
                description: "An option pricing engine I built in C++ to mess around with quantitative finance. Comes with a Python SDK, \
                REST backend, and a live dashboard to play with.",
                image: "https://cdn.jsdelivr.net/gh/devicons/devicon@v2.15.1/icons/cplusplus/cplusplus-original.svg",
                tech: ["C++17", "Black-Scholes PDEs", "Crank-Nicolson", "SIMD (AVX2/FMA)", "Auto-diff (Greeks)", "Python SDK", "FastAPI"],
                link: "https://pypi.org/project/nablaquant/"
              },
              {
                title: "TinyGNN",
                description: "Built lightweight C++17 engine for high-performance, memory-efficient sparse GNN inference.",
                image: "https://dist.neo4j.com/wp-content/uploads/20230404132329/prett-graph-2.png",
                tech: ["C++17", "OpenMP", "GNNs", "Python bindings", "Valgrind"],
                link: "https://pypi.org/project/tinygnn/"
              },
              {
                title: "JBAC Strategy Foundry (jsf-core)",
                description: "Built end-to-end quant engine with backtesting, portfolio construction, ML validation, NLP sentiment (FinBERT), paper trading, alerts, and a real-time dashboard. Educational only.",
                image: "data:image/jpeg;base64,",
                tech: ["Python", "Tensorflow", "Scikit-Learn", "Streamlit", "Trading/News APIs"],
                link: "https://pypi.org/project/jsf-core/"
              },
              {
                title: "EZ-Chess",
                description: "Explainable chess analysis tool using LLMs with MCP-style tooling (Stockfish analysis, Lichess API)",
                image: "data:image/png;base64,",
                tech: ["Python", "Tkinter", "Stockfish", "MCP", "Ollama/Groq"],
                link: "https://pypi.org/project/ez-chess/"
              },
              {
                title: "cybersec-scanner",
                description: "Developed privacy-first Python Library/SDK for efficient and safe software development",
                image: "data:image/png;base64,",
                tech: ["Python", "Git", "Mitmproxy", "Ollama"],
                link: "https://pypi.org/project/cybersec-scanner/"
              },
              
              {title: "AI Trading Coach",
               description: "An AI-powered trading education platform that helps develop smart trading strategies using real-time market analysis and paper trading to help develop market intuition.",
               image: "data:image/jpeg;base64,",
               tech: ["Python", "FastAPI", "AWS", "Docker", "Google OAuth"],
               link: "https://trading.jbac.dev/"
              },
              {title: "YtQGen",
               description: "Open source Python Library/SDK to generate YouTube video transcripts, summaries and Q&A pairs using LLMs.",
               image: "data:image/png;base64,",
               tech: ["Python", "GitHub", "LLM APIs", "PyTest", "PyPi"],
               link: "https://pypi.org/project/ytqgen/"
              },
              {
                title: "Mock Interviewer AI",
                description: "Fully automated mock interview platform that simulates real interviews using AI in great depth, providing instant feedback and interview transcripts to help users improve their skills.",
                image: "data:image/jpeg;base64,",
                tech: ["Streamlit", "FastAPI", "gpt-oss-20b/voxtral-mini-latest", "PostgreSQL", "AWS S3", "Render"],
                link: "https://interview.jbac.dev/"
              },
              {
                title: "Edu QGen",
                description: "Generates concise summaries and structured questionnaires (length by user input) from any uploaded video within 1-2 mins, saves pdf files for future reference.",
                image: "data:image/jpeg;base64,",
                tech: ["React.js", "FastAPI", "gpt-oss-20b/voxtral-mini-latest", "GCP (e2.small)", "AWS S3", "AWS DynamoDB", "Google OAuth"],
                link: "https://questionnaire.jbac.dev/"
              },
              {
                title: "Hackathon Scraper",
                description: "Multi-threaded, automated tool for regularly gathering worldwide hackathons (upto 550+) from premier hackathon websites in <3 mins.",
                image: "data:image/png;base64,",
                tech: ["Selenium", "BeautifulSoup", "Flask", "Multi-threading", "JavaScript", "GitHub Actions"],
                link: "https://hackathons.jbac.dev/"
              }
            ].map((product, index) => (
              <motion.div
                key={index}
                className="project-card tilt-card"
                variants={cardVariants}
                onMouseMove={handleCardGlow}
                onMouseLeave={resetCardTilt}
              >
                <div className="card-glow-overlay" />
                <div className="tilt-glare" />
                <div className="card-accent-bar" />
                <div className="project-image-wrap">
                  <img src={product.image} alt={product.title} className="project-image" />
                  <div className="project-image-overlay" />
                </div>
                <span className="card-index">{String(index + 1).padStart(2, '0')}</span>
                <div className="project-content">
                  <h3 className="project-title">{product.title}</h3>
                  <p className="project-description">{product.description}</p>
                  <div className="project-tech">
                    {product.tech.map(tech => (
                      <span key={tech} className="tech-tag">
                        {tech}
                      </span>
                    ))}
                  </div>
                  <div className="project-links">
                    <a href={product.link} className="project-link" target="_blank" rel="noopener noreferrer">
                      <ExternalLink size={16} />
                      Try it
                    </a>
                  </div>
                </div>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </section>
  );
};

export default Products;